import{_ as p,a0 as r,w as i,s as u,ao as d,I as n,x as o,a1 as e,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"埃隆·馬斯克認為推特的算法應該開源 | LCTT x X-CMD","titleTemplate":false,"description":"埃隆·馬斯克認為推特的算法應該開源 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"埃隆·馬斯克認為推特的算法應該開源 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"埃隆·馬斯克認為推特的算法應該開源 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220415 Elon Musk Believes Twitter Algorithm Should Be Open-Source","title":"埃隆·馬斯克認為推特的算法應該開源","tag":"202204","desc":""},"relativePath":"202204/20220415 Elon Musk Believes Twitter Algorithm Should Be Open-Source.md","filePath":"[post].md"}'),a={name:"202204/20220415 Elon Musk Believes Twitter Algorithm Should Be Open-Source.md"};function m(f,t,T,k,g,x){const s=r("Link");return i(),u("div",null,[t[20]||(t[20]=d('<h1 id="埃隆·馬斯克認為推特的算法應該開源" tabindex="-1">埃隆·馬斯克認為推特的算法應該開源 <a class="header-anchor" href="#埃隆·馬斯克認為推特的算法應該開源" aria-label="Permalink to “埃隆·馬斯克認為推特的算法應該開源”">​</a></h1><blockquote><p>埃隆·馬斯克希望推特開源他們的算法。這會促進言論自由嗎？以下是他的説法。</p></blockquote><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/04/elon-musk-twitter-algorithm-opensource.jpg" alt=""></p><p>沒錯，埃隆·馬斯克又搞了一個大新聞，這已經算是他的日常操作了。</p><p>然而，這一次的新聞非常有趣。他提出了要以大約 <strong>430 億美元</strong> 收購推特。</p><p>從技術上講，他的報價遠遠超過了市場價格，這也就是為什麼許多媒體稱他這是在試圖“惡意收購”。</p><p>考慮到這個激進的報價，我們還不確定這次收購是否會成功。不過，在一次 TED 演講中，埃隆·馬斯克還分享了他對於推特應該如何推動言論自由的一些想法。</p><h3 id="推特的算法應該開源" tabindex="-1">推特的算法應該開源 <a class="header-anchor" href="#推特的算法應該開源" aria-label="Permalink to “推特的算法應該開源”">​</a></h3><p>埃隆·馬斯克認為，推特應該將算法開源，以促進平台的透明度。</p><p>當然，推特作為一個平台，目前仍在爆炸式發展，很難預測。推特團隊在某些事情上也會採取果斷行動，不管用户認為它是否正確。</p><p>雖然推特的內部決定在紙面上看起來很好，但這種沒有透明度的大規模平台總是會存在問題的。</p><p>因此，埃隆·馬斯克有一個觀點：無論你是否認同或相信推特的決定，透明/開源只會有助於加強現有的價值觀。</p><p>嗯，難怪我們喜歡開源。</p><p>這裏引用他的原話：</p><blockquote><p>“因此，我認為推特應該做的事情之一就是開源它的算法，所有推文的修改都應該是透明的，任何人都可以看到這個修改，哪怕是加粗一段文字或是取消加粗它。這樣一來，幕後操縱將不復存在，無論是算法還是人工。”</p></blockquote>',15)),n("p",null,[t[2]||(t[2]=o("另一方面，當我們把推特當作一個某種程度上的開源平台來談論時，我不由自主地想到了 ",-1)),e(s,{href:"https://joinmastodon.org/"},{default:l(()=>[...t[0]||(t[0]=[o("Mastodon",-1)])]),_:1}),t[3]||(t[3]=o("。你也可以在 ",-1)),e(s,{href:"https://mastodon.social/@itsfoss"},{default:l(()=>[...t[1]||(t[1]=[o("Mastodon",-1)])]),_:1}),t[4]||(t[4]=o(" 上找到我們，如果你還沒有用過它的話。",-1))]),t[21]||(t[21]=n("p",null,"誠然，推特有很大的增長潛力，無論好壞，它都在不斷擴張。但是，開源理念能否幫助這個平台？我個人認為可以，但這是一個巨大的變革，不能指望一夜之間就能實現。",-1)),t[22]||(t[22]=n("p",null,"當然，即使埃隆·馬斯克成功地收購了推特，也沒有人能夠預測他會對推特做什麼。説實話，他就像任何複雜算法一樣不可預測。",-1)),t[23]||(t[23]=n("p",null,"那麼，你是如何看待這個新聞的呢？你相信埃隆·馬斯克説的話嗎？歡迎在下面的評論中分享你的想法。",-1)),t[24]||(t[24]=n("hr",null,null,-1)),n("p",null,[t[6]||(t[6]=o("via: ",-1)),e(s,{href:"https://news.itsfoss.com/elon-musk-twitter-open-source/"},{default:l(()=>[...t[5]||(t[5]=[o("https://news.itsfoss.com/elon-musk-twitter-open-source/",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=o("作者：",-1)),e(s,{href:"https://news.itsfoss.com/author/ankush/"},{default:l(()=>[...t[7]||(t[7]=[o("Ankush Das",-1)])]),_:1}),t[12]||(t[12]=o(" 選題：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[8]||(t[8]=[o("lujun9972",-1)])]),_:1}),t[13]||(t[13]=o(" 譯者：",-1)),e(s,{href:"https://github.com/lkxed"},{default:l(()=>[...t[9]||(t[9]=[o("lkxed",-1)])]),_:1}),t[14]||(t[14]=o(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[10]||(t[10]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=o("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[15]||(t[15]=[o("LCTT",-1)])]),_:1}),t[18]||(t[18]=o(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:l(()=>[...t[16]||(t[16]=[o("Linux中國",-1)])]),_:1}),t[19]||(t[19]=o(" 榮譽推出",-1))])])}const b=p(a,[["render",m]]);export{S as __pageData,b as default};
